private fun parseIcons(data:String)=data.lineSequence().map { line ->
    val fields=line.split('|')
    CategoryIcon(fields[0],fields[1],fields[2],fields[3],fields.drop(4))
}.toList()

val categoryIconGroups:List<CategoryIconGroup> by lazy { listOf(
    CategoryIconGroup("food","餐饮","食事",parseIcons(DATA_FOOD)),
    CategoryIconGroup("transport","交通","交通",parseIcons(DATA_TRANSPORT)),
    CategoryIconGroup("shopping","购物","買い物",parseIcons(DATA_SHOPPING)),
    CategoryIconGroup("home","居住","住まい",parseIcons(DATA_HOME)),
    CategoryIconGroup("fun","娱乐","娯楽",parseIcons(DATA_FUN)),
    CategoryIconGroup("health","医疗健康","医療・健康",parseIcons(DATA_HEALTH)),
    CategoryIconGroup("learn","学习工作","学び・仕事",parseIcons(DATA_LEARN)),
    CategoryIconGroup("social","人情家庭","交際・家族",parseIcons(DATA_SOCIAL)),
    CategoryIconGroup("finance","金融","お金",parseIcons(DATA_FINANCE)),
    CategoryIconGroup("other","其他","その他",parseIcons(DATA_OTHER))
) }
private val iconsById by lazy { categoryIconGroups.flatMap{it.icons}.associateBy{it.id} }
private val groupsByIconId by lazy { categoryIconGroups.flatMap{g->g.icons.map{it.id to g}}.toMap() }
fun categoryIconOf(id:String?):CategoryIcon?=iconsById[id]
fun categoryIconGroupOf(iconId:String?):CategoryIconGroup?=groupsByIconId[iconId]
